DP_CSS = ".riscv-dp{max-width:1100px;color-scheme:light;background:#fff}\n.riscv-dp svg.dp-svg{width:100%;max-width:100%;height:auto;display:block;user-select:none}\n.dp-error{padding:10px;border:1px solid #d40000;background:#fff0f0;color:#900;font:13px system-ui,sans-serif}\n.dp-fallback{color:#666;font:13px system-ui,sans-serif}\n/* wires */\n.dp-wire{outline:none}\n.dp-wire .hit{stroke:transparent;stroke-width:9;fill:none;stroke-linecap:round;stroke-linejoin:round}\n.dp-wire .line,.dp-wire .chev{stroke:#000;stroke-width:1.1;fill:none;stroke-linejoin:round}\n.dp-wire .core{display:none;stroke:#fff;stroke-width:1.1;fill:none}\n.dp-wire .head{fill:#000;stroke:none}\n.dp-wire .xmark{display:none;font:700 9px system-ui,sans-serif;fill:#000;stroke:#fff;stroke-width:2.4;paint-order:stroke;pointer-events:none}\n.dp-wire.thick .line,.dp-wire.thick .chev{stroke-width:3.2}\n.dp-wire.thick.unset .line,.dp-wire.thick.unset .chev{stroke:#a3a7ab}\n.dp-wire.thick.unset .head{fill:#a3a7ab}\n.dp-wire.on .line,.dp-wire.on .chev{stroke:#ff1010}\n.dp-wire.on .head{fill:#ff1010}\n.dp-junc{fill:#000}\n.dp-junc.on{fill:#ff1010;stroke:#ff1010}\n.dp-wire:not(.interactive){pointer-events:none}\n.dp-tips .dp-wire{pointer-events:auto}\n.dp-edit .dp-wire.interactive{cursor:pointer}\n.dp-edit .dp-wire.interactive:not(.on):hover .line{stroke:#ff8a8a}\n.dp-edit .dp-wire.interactive:not(.on):hover .head{fill:#ff8a8a}\n.dp-edit .dp-wire.thin.interactive:hover .line{stroke-width:2.4}\n.dp-edit .dp-wire.interactive.on:hover .line{stroke:#d40000}\n.dp-wire:focus-visible .line{stroke:#0a66ff;stroke-width:3.2}\n.dp-wire.bad .line,.dp-wire.bad .chev{stroke-dasharray:4 2.6}\n.dp-lead{stroke:#8c8c8c;stroke-width:.5;fill:none;pointer-events:none}\n/* boxes */\n.dp-vbox{display:flex;align-items:center;width:100%;height:100%;box-sizing:border-box;font:600 7px/1 ui-monospace,Menlo,Consolas,monospace;background:#c9c9c9;border:.6px solid #777;border-radius:1.5px;color:#000;overflow:hidden}\n.dp-vbox.fixed{background:#e4e4e4;border-style:dashed}\n.dp-vbox .pre{padding-left:2px;color:#444;user-select:none}\n.dp-vbox input{flex:1;min-width:0;width:100%;height:100%;border:0;background:transparent;font:inherit;color:#000;padding:0 1px;margin:0;outline:none;text-align:left}\n.dp-vbox .gl{display:none;padding-right:2px}\n.dp-vbox:focus-within{background:#e8e8e8;outline:1.4px solid #0a66ff}\n.dp-vbox.bad{background:#ffd6d6;outline:1.4px solid #d40000}\n.dp-vbox.good{outline:1.4px solid #1a8a2e}\n/* legend and toolbar */\n.dp-bar{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:6px 18px;margin:6px 0 2px;font:12.5px/1.35 system-ui,-apple-system,sans-serif;color:#333}\n.dp-legend{display:flex;flex-wrap:wrap;gap:4px 18px}\n.dp-ent{display:inline-flex;align-items:center;gap:5px}\n.dp-sw{vertical-align:middle;overflow:visible}\n.dp-swbox{display:inline-flex;width:30px;height:14px;font-size:9px;padding-right:0}\n.dp-legend .cb{display:none}\n.dp-cb .dp-legend .cb{display:inline}\n.dp-cb .dp-legend .nm{display:none}\n.dp-cbl{display:inline-flex;align-items:center;gap:4px;cursor:pointer;white-space:nowrap}\n/* colorblind mode: blue instead of red, patterns and marks instead of colour alone */\n.dp-cb .dp-wire.on .line,.dp-cb .dp-wire.on .chev{stroke:#0072B2}\n.dp-cb .dp-wire.on .head{fill:#0072B2}\n.dp-cb .dp-junc.on{fill:#0072B2;stroke:#0072B2}\n.dp-cb .dp-wire.thick.on .core{display:block}\n.dp-cb .dp-wire.thick.unset .line,.dp-cb .dp-wire.thick.unset .chev{stroke:#555;stroke-dasharray:.1 4.4;stroke-linecap:round}\n.dp-cb .dp-wire.bad .xmark{display:block}\n.dp-cb .dp-edit .dp-wire.interactive:not(.on):hover .line,.dp-cb.dp-edit .dp-wire.interactive:not(.on):hover .line{stroke:#7fb2d6}\n.dp-cb .dp-vbox.good{outline:1.6px solid #004e7a}\n.dp-cb .dp-vbox.good .gl,.dp-cb .dp-vbox.bad .gl{display:inline;font-weight:700}\n.dp-cb .dp-vbox.good .gl::before{content:'\\2713'}\n.dp-cb .dp-vbox.bad .gl::before{content:'\\2717'}\n.dp-cb .dp-vbox.bad{background:#ffe3b8;outline:1.6px dashed #8a4b00}\n"
