WIZ_CSS = '.dpw{max-width:1100px;font:15px/1.45 system-ui,-apple-system,Segoe UI,sans-serif;color:#111}\n.dpw-top{display:flex;flex-wrap:wrap;gap:10px 18px;align-items:center;justify-content:space-between;margin-bottom:6px}\n.dpw-steps{display:flex;gap:6px;flex-wrap:wrap}\n.dpw-pill{padding:2px 10px;border-radius:999px;background:#e9ecef;color:#495057;font-size:13px;white-space:nowrap}\n.dpw-pill.cur{background:#0a66ff;color:#fff;font-weight:600}\n.dpw-pill.done{background:#d3f9d8;color:#1b5e20}\n.dpw-load{font-size:13px;color:#495057}\n.dpw-load input{font-size:13px;max-width:220px}\n.dpw h4{margin:8px 0 2px;font-size:19px}\n.dpw-help{margin:0 0 8px;color:#343a40}\n.dpw-info{font-size:13px;color:#495057;margin:2px 0 8px}\n.dpw-msg{min-height:0;margin:6px 0;padding:0;font-size:14px}\n.dpw-msg.err{padding:8px 10px;border:1px solid #d40000;background:#fff0f0;color:#900;border-radius:6px}\n.dpw-msg.ok{padding:8px 10px;border:1px solid #1a8a2e;background:#f0fff2;color:#145a22;border-radius:6px}\n.dpw-bar{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0}\n.dpw-btn{font:inherit;font-size:14px;padding:6px 14px;border:1px solid #868e96;border-radius:6px;background:#f1f3f5;color:#111;cursor:pointer}\n.dpw-btn:hover{background:#e3e7ea}\n.dpw-btn.primary{background:#0a66ff;border-color:#0a66ff;color:#fff;font-weight:600}\n.dpw-btn.primary:hover{background:#0857d6}\n.dpw-btn.danger{color:#a30000;border-color:#e0a0a0}\n.dpw-final{margin-top:10px}\n.dpw-final label{display:block;font-weight:600;margin:10px 0 3px}\n.dpw-final input[type=text]{width:100%;max-width:520px;font:15px ui-monospace,Menlo,Consolas,monospace;padding:5px 8px;border:1px solid #868e96;border-radius:6px}\n.dpw-final textarea{width:100%;height:230px;font:12px/1.35 ui-monospace,Menlo,Consolas,monospace;padding:8px;border:1px solid #868e96;border-radius:6px;background:#f8f9fa;box-sizing:border-box}\n.dpw-steps-list{margin:8px 0 0;padding-left:20px;color:#343a40;font-size:14px}\n.dpw-diagram-wrap{overflow-x:auto}\n\n.dpw-pre label{display:block;font-weight:600;margin:10px 0 3px}\n.dpw-pre input[type=text],.dpw-pre select{font:15px ui-monospace,Menlo,Consolas,monospace;padding:5px 8px;border:1px solid #868e96;border-radius:6px;width:100%;max-width:520px;box-sizing:border-box}\n.dpw-pre .dpw-check{font-weight:400;display:block;margin:12px 0 4px}\n.dpw-pre .dpw-check input{width:auto;margin-right:6px}\n.dpw-edit{margin-top:18px;font-size:14px}\n.dpw-edit textarea{width:100%;height:120px;font:12px/1.35 ui-monospace,Menlo,Consolas,monospace;padding:8px;border:1px solid #868e96;border-radius:6px;box-sizing:border-box}\n.dpw [hidden]{display:none !important}\n.dpw-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:8px 16px;max-width:620px}\n.dpw-grid label,.dpw-boxopt label{display:block;font-weight:600;margin:8px 0 3px}\n.dpw-grid input{width:100%;box-sizing:border-box;font:15px ui-monospace,Menlo,Consolas,monospace;padding:5px 8px;border:1px solid #868e96;border-radius:6px}\n.dpw-opts{display:flex;flex-direction:column;gap:4px;margin:10px 0}\n.dpw-opts label{font-weight:400;display:flex;align-items:center;gap:6px;margin:0}\n.dpw-boxopt{display:flex;flex-wrap:wrap;align-items:center;gap:8px 12px;margin:6px 0}\n.dpw-boxopt label{display:inline;margin:0}\n.dpw-boxopt select{font:14px system-ui;padding:3px 6px;border:1px solid #868e96;border-radius:6px}\n.dpw-note{font-size:13px;color:#495057}\n'
WIZ_BODY = '<div class="dpw" id="dpw">\n  <div class="dpw-top"><div class="dpw-steps" id="dpw-steps"></div></div>\n  <h4 id="dpw-title">Loading&hellip;</h4>\n  <p class="dpw-help" id="dpw-help">If this message stays, JavaScript in this question is not running: press F12 and check the Console for red errors.</p>\n  <div class="dpw-info" id="dpw-info"></div>\n  <div class="dpw-msg" id="dpw-msg" role="alert"></div>\n  <div class="dpw-pre" id="dpw-pre" hidden>\n    <label for="dpw-instr">Instruction</label>\n    <input type="text" id="dpw-instr" placeholder="e.g. andi x5, x6, 0x1" autocomplete="off" spellcheck="false">\n    <div id="dpw-branchrow" hidden>\n      <label for="dpw-taken">Branch outcome</label>\n      <select id="dpw-taken"><option value="true">taken</option><option value="false">not taken</option></select>\n    </div>\n    <label class="dpw-check"><input type="checkbox" id="dpw-ctl"> Also add value boxes for the control signals (PCSel, RegWEn, BSel, ASel, MemRW, WBSel, BrUn)</label>\n    <div class="dpw-bar" id="dpw-prebar"></div>\n    <details class="dpw-edit"><summary>Edit an existing problem</summary>\n      <p class="dpw-help">Paste the <code>&lt;pl-riscv-datapath&gt;</code> tag from its <code>question.html</code> (old or new format).</p>\n      <textarea id="dpw-paste" spellcheck="false" placeholder="&lt;pl-riscv-datapath answers-name=&quot;dp&quot; ...&gt;&lt;/pl-riscv-datapath&gt;"></textarea>\n      <div class="dpw-bar" id="dpw-loadbar"></div>\n    </details>\n  </div>\n  <div class="dpw-bar" id="dpw-bar"></div>\n  <div class="dpw-boxopt" id="dpw-boxopt" hidden>\n    <label for="dpw-newbase">Base for new boxes:</label>\n    <select id="dpw-newbase"><option value="hex">hex (0x)</option><option value="binary">binary (0b)</option><option value="decimal">decimal</option></select>\n    <span class="dpw-note">Each box keeps the base it was created with. Binary and decimal boxes hold up to 8 characters on data wires and 2 on control signals.</span>\n  </div>\n  <div class="dpw-diagram-wrap" id="dpw-diagram-wrap"><div class="riscv-dp" id="dpw-diagram" data-init="1"></div></div>\n  <div class="dpw-final" id="dpw-final" hidden>\n    <div class="dpw-grid">\n      <div><label for="dpw-name">answers-name</label><input type="text" id="dpw-name" value="dp" autocomplete="off" spellcheck="false"></div>\n      <div><label for="dpw-wp">Points per thick wire</label><input type="number" id="dpw-wp" min="0" step="any" value="1"></div>\n      <div><label for="dpw-bp">Points per box</label><input type="number" id="dpw-bp" min="0" step="any" value="1"></div>\n    </div>\n    <div class="dpw-opts">\n      <label><input type="radio" name="dpw-fmt" id="dpw-fmt-full" value="full" checked> Full: every wire listed</label>\n      <label><input type="radio" name="dpw-fmt" id="dpw-fmt-compact" value="compact"> Compact: only wires that differ from the instruction\'s defaults</label>\n      <label><input type="checkbox" id="dpw-legend" checked> Show the legend</label>\n      <label><input type="checkbox" id="dpw-tips"> Show wire-name tooltips to students</label>\n    </div>\n    <label for="dpw-out">Tag to paste into question.html</label>\n    <textarea id="dpw-out" readonly spellcheck="false"></textarea>\n    <div class="dpw-bar" id="dpw-bar2"></div>\n    <ol class="dpw-steps-list">\n      <li>Open the question\'s <code>question.html</code> in PrairieLearn (Files, then Edit).</li>\n      <li>Paste the tag where the diagram should appear, and write your question text around it inside a <code>&lt;pl-question-panel&gt;</code>.</li>\n      <li>Every line is editable by hand: change a wire\'s <code>weight</code>, <code>mutable</code>, <code>initial-state</code> or <code>solution-state</code>, or move a value box by changing its <code>location</code>.</li>\n      <li>Save, open <b>Preview</b>, and grade the correct answer once to confirm full marks.</li>\n    </ol>\n  </div>\n</div>\n'

TAG = "pl-riscv-datapath"
CONTROL_WIRES = ["pcsel__pcmux_sel", "regwen__reg_wen", "immsel__immgen", "brun__brcomp", "brcomp_breq__ctrl",
                 "brcomp_brlt__ctrl", "bsel__bmux_sel", "asel__amux_sel", "alusel__alu", "memrw__dmem", "wbsel__wbmux_sel"]
CONTROL_REV = {w: k for k, w in CONTROL.items()}
BASES = ("hex", "binary", "decimal")
BASE_RADIX = {"hex": 16, "binary": 2, "decimal": 10}
BASE_PREFIX = {"hex": "0x", "binary": "0b", "decimal": ""}

COMMON_ATTRIBS = {"answers-name", "mode", "instruction", "branch-taken", "legend", "tooltips", "weight"}
LEGACY_ATTRIBS = {"answer-wires", "bold-wires", "initial-wires", "initial-off-wires", "locked-wires", "value-boxes",
                  "scoring-mode", "wire-points", "value-points"}
WIRE_NEW = {"name", "initial-state", "solution-state", "mutable", "weight"}
WIRE_OLD = {"name", "state", "value", "initial", "locked", "bold"}
BOX_ATTRS = {"name", "location", "base", "size", "solution", "initial-value", "mutable", "weight"}


# ---------------------------------------------------------------- helpers
def _err(msg):
    return ValueError("%s: %s" % (TAG, msg))


def _split(s):
    return [t for t in re.split(r"[,\s]+", s or "") if t]


def _label(w):
    return w.replace("__", " \u2192 ").replace("_", " ")


def _element(element_html):
    return lxml.html.fragment_fromstring(element_html)


def _is_builder(el):
    return (el.get("mode") or "").strip().lower() == "builder"


def _name(el):
    name = (el.get("answers-name") or "").strip()
    if not name:
        raise _err("answers-name is required")
    return name


def _bool(v, what, default=None):
    if v is None:
        return default
    t = v.strip().lower()
    if t == "true":
        return True
    if t == "false":
        return False
    raise _err("%s must be true or false (got %r)" % (what, v))


def _number(el, attr, default):
    raw = el.get(attr)
    if raw is None:
        return default
    try:
        v = float(raw)
    except ValueError:
        raise _err("%s must be a number (got %r)" % (attr, raw))
    if v < 0:
        raise _err("%s must not be negative" % attr)
    return int(v) if v == int(v) else v


def _parse_val(s, base):
    """'0x1F' / '1f' (hex), '0b101' / '101' (binary), '12' (decimal) -> int, or None if invalid."""
    if isinstance(s, int) and not isinstance(s, bool):
        return s
    t = str(s).strip().lower().replace("_", "")
    pre = BASE_PREFIX[base]
    if pre and t.startswith(pre):
        t = t[len(pre):]
    allowed = {"hex": "0123456789abcdef", "binary": "01", "decimal": "0123456789"}[base]
    if not t or any(c not in allowed for c in t):
        return None
    return int(t, BASE_RADIX[base])


def _fmt(v, base):
    return {"hex": format(v, "x"), "binary": format(v, "b"), "decimal": str(v)}[base]


def _hex(s):
    return _parse_val(s, "hex")


def _part_matches(part, token):
    return part == token or part.startswith(token + "_")


def _wire_list(value, what):
    """Wire names or groups (all | control | to:<component> | from:<component>), for the legacy list attributes."""
    out = []
    for tok in _split(value):
        low = tok.lower()
        if tok in WIRE_IDS:
            found = [tok]
        elif low == "all":
            found = list(WIRE_IDS)
        elif low == "control":
            found = list(CONTROL_WIRES)
        elif low.startswith("to:") or low.startswith("from:"):
            side, comp = low.split(":", 1)
            idx = 1 if side == "to" else 0
            found = [w for w in WIRE_IDS if _part_matches(w.split("__")[idx], comp)]
            if not found:
                raise _err("%r in %s matches no wires" % (tok, what))
        else:
            raise _err("unknown wire or group %r in %s" % (tok, what))
        out += found
    return out


# ---------------------------------------------------------------- the instruction defaults
def _preset(el):
    """(set of wires ON, control values) from the instruction, or (empty, {}) when there is none."""
    instruction = (el.get("instruction") or "").strip()
    if not instruction:
        return set(), {}
    tok = instruction.split()[0].lower().rstrip(",")
    mnemonic = ALIASES.get(tok, tok)
    preset = PRESETS.get(mnemonic)
    if preset is None:
        known = sorted(set(PRESETS) | set(ALIASES))
        raise _err("no preset for instruction %r. Supported: %s. Or leave out instruction and set every "
                   "solution-state yourself." % (tok, ", ".join(known)))
    if preset.get("branch"):
        taken = (el.get("branch-taken") or "").strip().lower()
        if taken not in ("true", "false"):
            raise _err('%s is a branch: set branch-taken="true" or branch-taken="false"' % mnemonic)
        preset = preset["taken" if taken == "true" else "not_taken"]
    return set(preset["on"]), dict(preset["ctl"])


# ---------------------------------------------------------------- the model (new format)
def _box_spec(child, ctl, seen_names, seen_locs):
    bad = set(child.attrib) - BOX_ATTRS
    if bad:
        raise _err("<pl-box> has unknown attribute(s): %s. Allowed: %s" % (", ".join(sorted(bad)), ", ".join(sorted(BOX_ATTRS))))
    loc = (child.get("location") or "").strip()
    if loc not in WIRE_IDS:
        raise _err("<pl-box> location %r is not a wire name (box places are on wires)" % loc)
    name = (child.get("name") or loc).strip()
    if name in seen_names:
        raise _err("two boxes are named %r" % name)
    if loc in seen_locs:
        raise _err("two boxes use the place on %r" % loc)
    seen_names.add(name)
    seen_locs.add(loc)
    base = (child.get("base") or "hex").strip().lower()
    if base not in BASES:
        raise _err('<pl-box name="%s"> base must be one of %s' % (name, ", ".join(BASES)))
    cap = WIRE_CAP[loc]
    size = int(_number(child, "size", cap))
    if size < 1 or size > cap:
        raise _err('<pl-box name="%s"> size %d does not fit the place on %s (1 to %d characters)' % (name, size, loc, cap))
    mutable = _bool(child.get("mutable"), '<pl-box name="%s"> mutable' % name, True)
    weight = _number(child, "weight", 0)

    def fit(v, what):
        if v >= BASE_RADIX[base] ** size:
            raise _err('<pl-box name="%s"> %s does not fit in %d %s character(s)' % (name, what, size, base))
        return v

    solution, initial = None, ""
    if mutable:
        sol = child.get("solution")
        if sol is None:
            if weight > 0:
                raise _err('<pl-box name="%s"> has weight but no solution' % name)
        elif sol.strip().lower() == "auto":
            short = CONTROL_REV.get(loc)
            if short is None or short not in ctl:
                raise _err('<pl-box name="%s"> solution="auto" needs an instruction and a control-signal place '
                           "with a defined value (got %s)" % (name, loc))
            solution = fit(int(ctl[short]), "solution")
        else:
            v = _parse_val(sol, base)
            if v is None:
                raise _err('<pl-box name="%s"> solution %r is not a valid %s value' % (name, sol, base))
            solution = fit(v, "solution")
        iv = child.get("initial-value")
        if iv is not None:
            v = _parse_val(iv, base)
            if v is None:
                raise _err('<pl-box name="%s"> initial-value %r is not a valid %s value' % (name, iv, base))
            initial = _fmt(fit(v, "initial-value"), base)
    else:
        iv = child.get("initial-value")
        if iv is None:
            raise _err('<pl-box name="%s"> mutable="false" needs an initial-value to show' % name)
        v = _parse_val(iv, base)
        if v is None:
            raise _err('<pl-box name="%s"> initial-value %r is not a valid %s value' % (name, iv, base))
        initial = _fmt(fit(v, "initial-value"), base)
        if weight:
            raise _err('<pl-box name="%s"> a box students cannot change cannot have a weight' % name)
    return {"name": name, "location": loc, "base": base, "size": size, "mutable": mutable,
            "initial": initial, "solution": solution, "weight": weight}


def _build_new(el):
    on, ctl = _preset(el)
    wires = {w: {"mutable": False, "initial": None, "solution": "on" if w in on else "off", "weight": 0} for w in WIRE_IDS}
    seen = set()
    for child in el.iter("pl-wire"):
        bad = set(child.attrib) - WIRE_NEW
        if bad:
            raise _err("<pl-wire> has unknown attribute(s): %s. Allowed: %s" % (", ".join(sorted(bad)), ", ".join(sorted(WIRE_NEW))))
        w = (child.get("name") or "").strip()
        if w not in WIRE_IDS:
            raise _err("<pl-wire> has unknown wire name %r" % w)
        if w in seen:
            raise _err("wire %r is listed twice" % w)
        seen.add(w)
        cfg = wires[w]
        cfg["mutable"] = _bool(child.get("mutable"), '<pl-wire name="%s"> mutable' % w, False)
        if child.get("initial-state") is not None:
            v = child.get("initial-state").strip().lower()
            if v not in ("unset", "on", "off"):
                raise _err('<pl-wire name="%s"> initial-state must be unset, on or off' % w)
            cfg["initial"] = v
        if child.get("solution-state") is not None:
            v = child.get("solution-state").strip().lower()
            if v not in ("on", "off"):
                raise _err('<pl-wire name="%s"> solution-state must be on or off' % w)
            cfg["solution"] = v
        cfg["weight"] = _number(child, "weight", 0)
    for w, cfg in wires.items():
        if cfg["initial"] is None:
            cfg["initial"] = "unset" if cfg["mutable"] else "off"
        if not cfg["mutable"]:
            if cfg["initial"] == "unset":
                raise _err('wire %s is not mutable, so its initial-state must be on or off (not unset)' % w)
            if cfg["weight"]:
                raise _err("wire %s is not mutable, so it cannot have a weight (students cannot change it)" % w)
    seen_names, seen_locs = set(), set()
    boxes = [_box_spec(c, ctl, seen_names, seen_locs) for c in el.iter("pl-box")]
    return wires, boxes


# ---------------------------------------------------------------- legacy tags -> the same model
def _build_legacy(el):
    unknown = set(el.attrib) - COMMON_ATTRIBS - LEGACY_ATTRIBS
    if unknown:
        raise _err("unknown attribute(s): %s" % ", ".join(sorted(unknown)))
    if el.get("scoring-mode") is not None:
        raise _err("scoring-mode was removed: every graded item now has a weight. Delete scoring-mode (each wire "
                   "counts for 1 point), or use the <pl-wire weight=...> format")
    on, ctl = _preset(el)
    boxes = {}
    if el.get("answer-wires") is not None:
        on = set(_wire_list(el.get("answer-wires"), "answer-wires"))
    vb = (el.get("value-boxes") or "none").strip().lower()
    if vb != "none":
        if not ctl:
            raise _err("value-boxes needs an instruction (it takes the values from the preset)")
        names = list(ctl) if vb == "control" else _split(vb)
        for n in names:
            if n not in CONTROL:
                raise _err("unknown control signal %r in value-boxes. Use: %s" % (n, ", ".join(CONTROL)))
            if n not in ctl:
                raise _err("%s has no defined value for this instruction, so it cannot be a value box" % n)
            boxes[CONTROL[n]] = format(int(ctl[n]), "x")
    bold = set(_wire_list(el.get("bold-wires"), "bold-wires")) if el.get("bold-wires") is not None else None
    directive = {}
    for w in _wire_list(el.get("initial-wires"), "initial-wires"):
        directive[w] = "on"
    for w in _wire_list(el.get("initial-off-wires"), "initial-off-wires"):
        directive[w] = "off"
    locked = set(_wire_list(el.get("locked-wires"), "locked-wires"))
    for child in el.iter("pl-wire"):
        bad = set(child.attrib) - WIRE_OLD
        if bad:
            raise _err("<pl-wire> has unknown attribute(s): %s" % ", ".join(sorted(bad)))
        w = (child.get("name") or "").strip()
        if w not in WIRE_IDS:
            raise _err("<pl-wire> has unknown wire name %r" % w)
        s = child.get("state")
        if s is not None:
            s = s.strip().lower()
            if s == "on":
                on.add(w)
            elif s == "off":
                on.discard(w)
            else:
                raise _err('<pl-wire name="%s"> state must be "on" or "off"' % w)
        if child.get("value") is not None:
            v = _hex(child.get("value"))
            if v is None:
                raise _err('<pl-wire name="%s"> value %r is not valid hex' % (w, child.get("value")))
            if v >= 16 ** WIRE_CAP[w]:
                raise _err('<pl-wire name="%s"> value %r needs more than %d hex digits' % (w, child.get("value"), WIRE_CAP[w]))
            boxes[w] = format(v, "x")
        b = child.get("bold")
        if b is not None:
            bold = set() if bold is None else bold
            if b.strip().lower() in ("true", "on"):
                bold.add(w)
            elif b.strip().lower() in ("false", "off"):
                bold.discard(w)
            else:
                raise _err('<pl-wire name="%s"> bold must be true or false' % w)
        i = child.get("initial")
        if i is not None:
            i = i.strip().lower()
            if i in ("on", "true"):
                directive[w] = "on"
            elif i in ("off", "false"):
                directive[w] = "off"
            elif i == "unset":
                directive[w] = "unset"
            else:
                raise _err('<pl-wire name="%s"> initial must be on, off or unset' % w)
        lk = child.get("locked")
        if lk is not None:
            if lk.strip().lower() in ("true", "on"):
                locked.add(w)
            elif lk.strip().lower() in ("false", "off"):
                locked.discard(w)
            else:
                raise _err('<pl-wire name="%s"> locked must be true or false' % w)
    has_source = bool(el.get("instruction")) or el.get("answer-wires") is not None or any(c.get("state") for c in el.iter("pl-wire"))
    if not has_source and not boxes:
        raise _err("no answer key: give an instruction, answer-wires, or <pl-wire state=\"on\"> children")
    if bold is not None and not bold:
        raise _err("bold-wires is empty (no wire is marked bold)")
    if bold is None and el.get("initial-off-wires") is not None:
        raise _err("initial-off-wires only applies when bold-wires is set")
    wp = _number(el, "wire-points", 1)
    vp = _number(el, "value-points", 1)
    wires = {}
    for w in WIRE_IDS:
        mutable = (bold is None or w in bold) and w not in locked
        d = directive.get(w)
        if mutable and bold is not None:
            initial = d if d in ("on", "off") else "unset"
        else:
            initial = "on" if d == "on" else "off"
        wires[w] = {"mutable": mutable, "initial": initial, "solution": "on" if w in on else "off",
                    "weight": wp if mutable else 0}
    bx = [{"name": w, "location": w, "base": "hex", "size": WIRE_CAP[w], "mutable": True, "initial": "",
           "solution": int(h, 16), "weight": vp} for w, h in sorted(boxes.items(), key=lambda kv: WIRE_IDS.index(kv[0]))]
    return wires, bx


def _build_spec(el):
    """Tag -> JSON-serializable model: per-wire settings, boxes, display options."""
    _name(el)
    kids = list(el.iter("pl-wire"))
    new = bool(list(el.iter("pl-box"))) or any(set(k.attrib) & (WIRE_NEW - {"name"}) for k in kids)
    old = any(set(k.attrib) & (WIRE_OLD - {"name"}) for k in kids) or any(a in el.attrib for a in LEGACY_ATTRIBS)
    if new and old:
        raise _err("this tag mixes the old format (answer-wires, bold-wires, value-boxes, <pl-wire state=...> ...) with "
                   "the wire-element format (<pl-wire mutable=... initial-state=... solution-state=... weight=...>, <pl-box>). "
                   "Use one or the other")
    if new:
        unknown = set(el.attrib) - COMMON_ATTRIBS
        if unknown:
            raise _err("unknown attribute(s): %s. Allowed: %s" % (", ".join(sorted(unknown)), ", ".join(sorted(COMMON_ATTRIBS))))
        wires, boxes = _build_new(el)
    else:
        wires, boxes = _build_legacy(el)
    total = sum(c["weight"] for c in wires.values()) + sum(b["weight"] for b in boxes if b["mutable"])
    if total <= 0:
        raise _err("nothing is graded: give at least one mutable wire or box a weight above 0")
    return {
        "wires": wires,
        "boxes": boxes,
        "legend": _bool(el.get("legend"), "legend", True),
        "tooltips": _bool(el.get("tooltips"), "tooltips", False),
        "weight": int(_number(el, "weight", 1)),
    }


# ---------------------------------------------------------------- grading
def _score(spec, wires, values):
    """wires: {wire: 1|0} the student's explicit states; values: {box name: text}. One grader for everything."""
    earned = possible = 0
    results, vres = {}, {}
    for w, cfg in spec["wires"].items():
        if cfg["weight"] <= 0:
            continue
        possible += cfg["weight"]
        s = wires.get(w)
        if s is None:
            s = {"on": 1, "off": 0}.get(cfg["initial"])      # untouched: its starting state (unset counts as wrong)
        if s == (1 if cfg["solution"] == "on" else 0):
            earned += cfg["weight"]
        else:
            results[w] = False
    for b in spec["boxes"]:
        if not b["mutable"] or b["weight"] <= 0:
            continue
        possible += b["weight"]
        got = _parse_val(values.get(b["name"], ""), b["base"])
        ok = got is not None and b["solution"] is not None and got == b["solution"]
        vres[b["name"]] = ok
        if ok:
            earned += b["weight"]
    score = max(0.0, min(1.0, earned / possible)) if possible else 0.0
    wrong = len(results) + sum(1 for v in vres.values() if not v)
    summary = "%s/%s points: %d graded item(s) incorrect or not set." % (format(earned, "g"), format(possible, "g"), wrong)
    return score, summary, results, vres


def _norm_state(sub):
    """Any stored submission -> ({wire: 1|0}, {box name: text}) or None."""
    if isinstance(sub, str):
        try:
            sub = json.loads(sub)
        except ValueError:
            return None
    if not isinstance(sub, dict):
        return None
    wires = sub.get("wires", {})
    if isinstance(wires, list):                       # older stored format: on-list plus off-list
        wires = dict({w: 1 for w in wires}, **{w: 0 for w in (sub.get("off") or [])})
    if not isinstance(wires, dict):
        wires = {}
    values = sub.get("values")
    return ({w: (1 if v else 0) for w, v in wires.items() if w in WIRE_IDS}, values if isinstance(values, dict) else {})


# ---------------------------------------------------------------- rendering
def _attr(obj):
    return html.escape(json.dumps(obj, separators=(",", ":")), quote=True)


def _assets(js, css):
    return "<style>\n%s\n</style>\n<script>\n%s\n</script>\n" % (css, js)


def _diagram(name, mode, spec, state=None, results=None, vresults=None, hidden=False):
    cfg = {"wires": {w: [1 if c["mutable"] else 0, {"on": 1, "off": 0, "unset": -1}[c["initial"]]] for w, c in spec["wires"].items()},
           "boxes": [{"n": b["name"], "loc": b["location"], "base": b["base"], "size": b["size"],
                      "m": 1 if b["mutable"] else 0, "i": b["initial"]} for b in spec["boxes"]],
           "legend": spec["legend"], "tips": spec["tooltips"]}
    a = ['class="riscv-dp"', 'data-mode="%s"' % mode, 'data-input="%s"' % html.escape(name, quote=True),
         'data-config="%s"' % _attr(cfg)]
    if state is not None:
        a.append('data-state="%s"' % _attr({"wires": state[0], "values": state[1]}))
    if results is not None:
        a.append('data-results="%s"' % _attr(results))
    if vresults is not None:
        a.append('data-vresults="%s"' % _attr(vresults))
    out = '<div %s><p class="dp-fallback">Loading datapath diagram&hellip; (if this message stays, JavaScript is not running: '\
          'press F12 and check the Console for red errors)</p></div>\n' % " ".join(a)
    if hidden:
        out += '<input type="hidden" name="%s">\n' % html.escape(name, quote=True)
    return out


def _solution_state(spec):
    wires = {w: (1 if c["solution"] == "on" else 0) for w, c in spec["wires"].items() if c["mutable"]}
    values = {b["name"]: _fmt(b["solution"], b["base"]) for b in spec["boxes"] if b["mutable"] and b["solution"] is not None}
    return wires, values


def render(element_html, data):
    el = _element(element_html)
    panel = data["panel"]
    if _is_builder(el):
        if panel != "question":
            return ""
        return ('<style>\n%s\n</style>\n%s\n<script>\n%s\n</script>\n<script>\n%s\n</script>\n'
                % (DP_CSS + "\n" + WIZ_CSS, WIZ_BODY, DP_JS, WIZ_JS))
    name = _name(el)
    spec = data["correct_answers"].get(name)
    if spec is None:
        raise _err("no answer key for %r (was prepare() run?)" % name)
    assets = _assets(DP_JS, DP_CSS)
    errors = data["format_errors"].get(name)
    sub = _norm_state(data["submitted_answers"].get(name))

    if panel == "question":
        editable = bool(data.get("editable", True))
        body = _diagram(name, "edit" if editable else "view", spec, state=sub, hidden=editable)
        if errors:
            body += '<div class="alert alert-danger" role="alert">%s</div>\n' % html.escape(str(errors))
        return body + assets
    if panel == "submission":
        if errors:
            return '<div class="alert alert-danger" role="alert">%s</div>\n' % html.escape(str(errors))
        if sub is None:
            return ""
        fb = data["feedback"].get(name) or {}
        summary = html.escape(fb.get("summary", ""))
        body = ('<p>%s</p>\n' % summary if summary else "")
        body += _diagram(name, "view", spec, state=sub, results=fb.get("results"), vresults=fb.get("vresults"))
        return body + assets
    if panel == "answer":
        return _diagram(name, "view", spec, state=_solution_state(spec)) + assets
    return ""


# ---------------------------------------------------------------- PrairieLearn phases
def prepare(element_html, data):
    el = _element(element_html)
    if _is_builder(el):
        return
    data["correct_answers"][_name(el)] = _build_spec(el)


def parse(element_html, data):
    el = _element(element_html)
    if _is_builder(el):
        return
    name = _name(el)
    spec = data["correct_answers"][name]
    raw = data["submitted_answers"].get(name)
    obj = raw if isinstance(raw, dict) else None
    if obj is None and isinstance(raw, str) and raw.strip():
        try:
            obj = json.loads(raw)
        except ValueError:
            obj = None
    if not isinstance(obj, dict) or not isinstance(obj.get("wires", {}), (dict, list)) or not isinstance(obj.get("values", {}), dict):
        data["format_errors"][name] = "No answer was received from the diagram. Please try again."
        return
    wires, values = _norm_state(obj)
    wires = {w: v for w, v in wires.items() if spec["wires"][w]["mutable"]}
    boxes = {b["name"]: b for b in spec["boxes"] if b["mutable"]}
    clean = {}
    for n, v in values.items():
        if n not in boxes:
            continue
        v = str(v or "").strip()
        if v and _parse_val(v, boxes[n]["base"]) is None:
            data["format_errors"][name] = "The value in %s is not a valid %s number." % (_label(boxes[n]["location"]), boxes[n]["base"])
            return
        clean[n] = v
    data["submitted_answers"][name] = {"wires": wires, "values": clean}


def grade(element_html, data):
    el = _element(element_html)
    if _is_builder(el):
        return
    name = _name(el)
    spec = data["correct_answers"][name]
    st = _norm_state(data["submitted_answers"].get(name))
    if st is None:
        return
    score, summary, results, vres = _score(spec, st[0], st[1])
    data["partial_scores"][name] = {"score": score, "weight": spec["weight"], "feedback": summary}
    data["feedback"][name] = {"results": results, "vresults": vres, "summary": summary}


def test(element_html, data):
    el = _element(element_html)
    if _is_builder(el):
        return
    name = _name(el)
    spec = data["correct_answers"][name]
    kind = data["test_type"]
    wires, values = _solution_state(spec)
    if kind == "correct":
        data["raw_submitted_answers"][name] = json.dumps({"wires": wires, "values": values})
        data["partial_scores"][name] = {"score": 1, "weight": spec["weight"]}
    elif kind == "incorrect":
        wires, values = dict(wires), dict(values)
        graded = [w for w, c in spec["wires"].items() if c["mutable"] and c["weight"] > 0]
        if graded:
            wires[graded[0]] = 0 if wires[graded[0]] else 1
        else:
            b = next(b for b in spec["boxes"] if b["mutable"] and b["weight"] > 0)
            values[b["name"]] = "0" if b["solution"] else "1"
        score, _, _, _ = _score(spec, wires, values)
        data["raw_submitted_answers"][name] = json.dumps({"wires": wires, "values": values})
        data["partial_scores"][name] = {"score": score, "weight": spec["weight"]}
    elif kind == "invalid":
        data["raw_submitted_answers"][name] = "this is not json"
        data["format_errors"][name] = "No answer was received from the diagram. Please try again."
    else:
        raise _err("unknown test_type %r" % kind)
